(x, y, t) => {
  const cx = 240, cy = 120;
  const s = [
    [160 + Math.sin(t*0.6)*100, 80 + Math.cos(t*0.4)*50, 0.08, 2.0],
    [320 + Math.cos(t*0.5)*100, 160 + Math.sin(t*0.7)*50, 0.1, 1.7],
    [240 + Math.sin(t*0.3+2)*140, 120 + Math.cos(t*0.5+1)*90, 0.06, 2.3],
    [100 + Math.cos(t*0.8+1)*80, 200 + Math.sin(t*0.6+3)*60, 0.12, 1.5],
    [380 + Math.sin(t*0.45+4)*90, 60 + Math.cos(t*0.55+2)*70, 0.09, 1.9]
  ];
  let act = 0, inh = 0;
  for (let i = 0; i < s.length; i++) {
    const dx = x - s[i][0], dy = y - s[i][1];
    const d = Math.sqrt(dx*dx + dy*dy);
    const w = Math.sin(d * s[i][2] - t * s[i][3]);
    const wt = i < 3 ? 0.28 : 0.08;
    act += w * wt;
    if (i < 2) { inh += Math.sin(d * 0.04 + t * 0.9 + i * 1.5) * 0.25; }
  }
  const wx = x*0.05 + Math.sin(y*0.02 + t*0.7)*8;
  const wy = y*0.05 + Math.cos(x*0.02 + t*0.6)*8;
  const warp = Math.sin(wx + t*0.8) + Math.sin(wy - t*1.1);
  inh += warp * 0.3;
  const fine1 = Math.sin((x+y)*0.15 + t*3) * 0.12;
  const fine2 = Math.sin((x-y)*0.12 - t*2.5) * 0.12;
  const fine3 = Math.sin(x*0.18 - y*0.08 + t*2.2) * 0.08;
  const dist = Math.sqrt((x-cx)**2 + (y-cy)**2);
  const ang = Math.atan2(y-cy, x-cx);
  const rad = Math.sin(dist*0.04 - t*1.5);
  const angW = Math.sin(ang*6 + t*0.4);
  const spiral = Math.sin(dist*0.03 + ang*3 - t*1.2) * 0.4;
  const pat2 = Math.tanh((rad + angW*0.5 + spiral) * 2);
  let rx = act - inh*0.75 + fine1 + fine2 + fine3;
  rx = Math.tanh(rx * 2.8);
  let rx2 = rx;
  rx2 = Math.tanh((rx2 + pat2*0.3) * 1.5);
  const pulse = 0.92 + Math.sin(t*0.3)*0.08;
  rx *= pulse;
  const blend = rx * 0.65 + pat2 * 0.35;
  const v = blend * 0.5 + 0.5;
  const edge = Math.abs(blend) * 0.3 + 0.7;
  const lum = 0.82 + Math.sin(rx * Math.PI * 2) * 0.18;
  const sat = 0.9 + Math.sin(rx * Math.PI * 1.5) * 0.1;
  const pal = [
    [8, 15, 58], [22, 72, 120], [45, 148, 138],
    [180, 165, 60], [218, 125, 55], [178, 58, 48],
    [85, 22, 65], [8, 15, 58]
  ];
  const idx = v * (pal.length - 1);
  const i = Math.min(idx | 0, pal.length - 2);
  const f = idx - i;
  const c0 = pal[i], c1 = pal[i+1];
  const smooth = f * f * (3 - 2 * f);
  let r = (c0[0] + (c1[0]-c0[0])*smooth) * lum * edge;
  let g = (c0[1] + (c1[1]-c0[1])*smooth) * lum * edge;
  let b = (c0[2] + (c1[2]-c0[2])*smooth) * lum * edge;
  const avg = (r+g+b)/3;
  r = avg + (r-avg)*sat;
  g = avg + (g-avg)*sat;
  b = avg + (b-avg)*sat;
  return [Math.min(255, Math.max(0, r))|0, Math.min(255, Math.max(0, g))|0, Math.min(255, Math.max(0, b))|0];
}
